-- SQL Script for importing hardcoded data to Database

-- 1. Add daily_recommended column to ingredients
ALTER TABLE `ingredients` ADD COLUMN IF NOT EXISTS `daily_recommended` decimal(10,2) NOT NULL DEFAULT 0.00;

-- 2. Update daily_recommended data to ingredients
UPDATE `ingredients` SET `daily_recommended` = 18.00 WHERE `ingredient_name` = 'เนื้อวัว';
UPDATE `ingredients` SET `daily_recommended` = 15.00 WHERE `ingredient_name` = 'น่องไก่';
UPDATE `ingredients` SET `daily_recommended` = 10.00 WHERE `ingredient_name` = 'ผักบุ้ง';
UPDATE `ingredients` SET `daily_recommended` = 10.00 WHERE `ingredient_name` = 'ถั่วงอก';
UPDATE `ingredients` SET `daily_recommended` = 3.00 WHERE `ingredient_name` = 'กุ้ง';
UPDATE `ingredients` SET `daily_recommended` = 1.00 WHERE `ingredient_name` = 'หมึก';
UPDATE `ingredients` SET `daily_recommended` = 3.00 WHERE `ingredient_name` = 'ไข่';

-- 3. Add image_url column to menus
ALTER TABLE `menus` ADD COLUMN IF NOT EXISTS `image_url` varchar(255) DEFAULT NULL;

-- 4. Update image_url data to menus
UPDATE `menus` SET `image_url` = 'images/ก๋วยเตี๋ยวน้ำข้น.jpg' WHERE `menu_id` = 'nam-khon';
UPDATE `menus` SET `image_url` = 'images/ก๋วยเตี๋ยวแห้ง.jpg' WHERE `menu_id` = 'haeng';
UPDATE `menus` SET `image_url` = 'images/ก๋วยเตี๋ยวต้มยำ.jpg' WHERE `menu_id` = 'tom-yam';
UPDATE `menus` SET `image_url` = 'images/ก๋วยเตี๋ยวต้มยำทะเล.png' WHERE `menu_id` = 'tom-yam-seafood';
UPDATE `menus` SET `image_url` = 'images/เกาเหลา.jpg' WHERE `menu_id` = 'kao-lao';


